#!/usr/bin/env bash
# SPDX-License-Identifier: GPL-2.0+
#
# Embed the E2631 rescue page into the U-Boot tree.
#
# The page is a single self-contained HTML file (no CDN, no i18n); this script
# gzip-compresses it deterministically (gzip -9 -n: no timestamp, no file name)
# and emits a C array plus a header with the frozen interface:
#
#   extern const unsigned char e2631_failsafe_html_gz[];
#   extern const unsigned int  e2631_failsafe_html_gz_len;
#
# The generated files are NOT committed: the uboot-build workflow runs this
# script after "git am" and before "make". A build without it fails at compile
# time because patch 0026 adds e2631_failsafe_asset.o to the Makefile.
#
# Usage:
#   tools/embed-failsafe.sh --outdir <uboot>/board/zte/zxhn-e2631 [--stats FILE]
#   tools/embed-failsafe.sh --check
#
# --check  only validates the gzip size and prints the numbers (CI gate; it does
#          not write anything). Exits non-zero when the page is over the limit.
# --max N  size limit in bytes, default 32768 (the E4 v2 page budget; authority:
#          evidence/e4-v2-contract-design-20261128.md, task-83 contract, raised
#          from the v1 6144-byte gate by task-87).
#
# The C output is deterministic for a given gzip version: no timestamps, no
# absolute paths, fixed line width and hex case.
set -euo pipefail

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
SRC="$ROOT/uboot-port/failsafe/e2631-failsafe.html"
OUTDIR=""
STATS=""
MODE=embed
MAX=32768

die() { printf 'embed-failsafe: %s\n' "$*" >&2; exit 1; }

usage() {
	cat <<'EOF'
usage: tools/embed-failsafe.sh --outdir DIR [--stats FILE] [--max BYTES]
       tools/embed-failsafe.sh --check [--max BYTES]
EOF
}

while [ $# -gt 0 ]; do
	case "$1" in
	--check) MODE=check ;;
	--src) SRC=${2:-}; shift ;;
	--outdir) OUTDIR=${2:-}; shift ;;
	--stats) STATS=${2:-}; shift ;;
	--max) MAX=${2:-}; shift ;;
	-h|--help) usage; exit 0 ;;
	*) usage >&2; die "unknown argument: $1" ;;
	esac
	[ $# -gt 0 ] && shift
done

command -v gzip >/dev/null 2>&1 || die "gzip not found"
command -v python3 >/dev/null 2>&1 || die "python3 not found"
[ -f "$SRC" ] || die "page source not found: $SRC"
case "$MAX" in
''|*[!0-9]*) die "--max must be a decimal byte count" ;;
esac

tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT
gzip -9 -n -c "$SRC" > "$tmp"
raw=$(stat -c%s "$SRC")
gz=$(stat -c%s "$tmp")
sha=$(sha256sum "$tmp" | awk '{print $1}')

printf 'failsafe page: raw %s B, gzip %s B (limit %s B), gzip sha256 %s\n' \
	"$raw" "$gz" "$MAX" "$sha"
[ "$gz" -le "$MAX" ] || die "gzip asset is $gz bytes, above the $MAX byte limit"

if [ "$MODE" = check ]; then
	exit 0
fi
[ -n "$OUTDIR" ] || die "--outdir is required for generation"
mkdir -p "$OUTDIR"

# Deterministic C emitter: bytes from the gzip stream, relative source name in
# the comment, fixed 12-bytes-per-line layout.
python3 - "$tmp" "$OUTDIR" "$raw" "$gz" <<'PY'
import sys

gz_path, outdir, raw, gz_len = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4]
data = open(gz_path, "rb").read()
assert len(data) == int(gz_len), "gzip size changed while reading"
assert len(data) <= 32768, "asset exceeds the E4 v2 page budget (task-83 contract: 32768 bytes)"

c_path = outdir.rstrip("/") + "/e2631_failsafe_asset.c"
h_path = outdir.rstrip("/") + "/e2631_failsafe_asset.h"
source = "uboot-port/failsafe/e2631-failsafe.html"

hdr = """/* SPDX-License-Identifier: GPL-2.0+ */
/* Frozen interface for the E2631 rescue page asset; see uboot-port/failsafe/README.md. */
#ifndef E2631_FAILSAFE_ASSET_H
#define E2631_FAILSAFE_ASSET_H

extern const unsigned char e2631_failsafe_html_gz[];
extern const unsigned int e2631_failsafe_html_gz_len;

#endif /* E2631_FAILSAFE_ASSET_H */
"""
open(h_path, "w", encoding="utf-8").write(hdr)

lines = []
for off in range(0, len(data), 12):
    chunk = data[off:off + 12]
    lines.append("\t" + ", ".join("0x%02x" % b for b in chunk) + ",")
body = "\n".join(lines)

c = """/* SPDX-License-Identifier: GPL-2.0+ */
/* Generated by tools/embed-failsafe.sh from %s -- do not edit. */
/* gzip payload: %s bytes (uncompressed page: %s bytes); served verbatim with
 * Content-Type: text/html and Content-Encoding: gzip, no inflate in U-Boot. */
#include "e2631_failsafe_asset.h"

const unsigned char e2631_failsafe_html_gz[] = {
%s
};

const unsigned int e2631_failsafe_html_gz_len = %s;
""" % (source, gz_len, raw, body, gz_len)
open(c_path, "w", encoding="utf-8").write(c)
print("wrote %s and %s" % (c_path, h_path))
PY

if [ -n "$STATS" ]; then
	mkdir -p "$(dirname "$STATS")"
	{
		printf 'source=uboot-port/failsafe/e2631-failsafe.html\n'
		printf 'raw_bytes=%s\n' "$raw"
		printf 'gzip_bytes=%s\n' "$gz"
		printf 'limit_bytes=%s\n' "$MAX"
		printf 'gzip_sha256=%s\n' "$sha"
		printf 'symbols=e2631_failsafe_html_gz,e2631_failsafe_html_gz_len\n'
	} > "$STATS"
	printf 'stats: %s\n' "$STATS"
fi
